class Solution {
public:
    int minimumIndex(vector<int>& nums) {
        int n = nums.size();
        // Boyer-Moore majority vote to find the dominant element x.
        int x = nums[0], cnt = 1;
        for (int i = 1; i < n; ++i) {
            if (nums[i] == x) {
                ++cnt;
            } else {
                --cnt;
                if (cnt == 0) {
                    x = nums[i];
                    cnt = 1;
                }
            }
        }
        // Total frequency f of the dominant element.
        long long f = 0;
        for (int i = 0; i < n; ++i) {
            if (nums[i] == x) ++f;
        }
        // Sweep split point i from 0 to n-2.
        long long f1 = 0;
        for (int i = 0; i < n - 1; ++i) {
            if (nums[i] == x) ++f1;
            long long f2 = f - f1;
            // x dominant in [0..i]  <=> 2*f1 > i+1
            // x dominant in [i+1..n-1] <=> 2*f2 > n-1-i
            if (2 * f1 > (long long)(i + 1) && 2 * f2 > (long long)(n - 1 - i)) {
                return i;
            }
        }
        return -1;
    }
};
